    t = t.lower().replace("\n", " ").replace("\r", " ").replace("\t", " ")
    return re.sub(r"\s+", " ", t).strip()

for split, src, dst in [
    ("train", "data/train-00000-of-00001.parquet", "/tmp/ft_train_lc.txt"),
    ("test", "data/test-00000-of-00001.parquet", "/tmp/ft_test_lc.txt"),
]:
