    print(f"{split}: {df.shape}", flush=True)
    with open(dst, "w", encoding="utf-8") as f:
        for lab, txt in zip(df["label"].tolist(), df["text"].tolist()):
            f.write(f"__label__{int(lab)} {clean(str(txt))}\n")
    print(f"wrote {dst}", flush=True)
